#!/usr/bin/env bash
# Generated by OrchestKit Claude Plugin
# Created: 2026-08-17

# Test: declared mcpServers must be callable (#3461)
#
# `mcpServers:` in agent frontmatter is METADATA. Claude Code ignores it for
# plugin agents; the actual capability grant is the `tools:` list. An agent
# declaring `mcpServers: [context7]` with no `mcp__context7__*` entry in
# `tools:` cannot call context7 and silently degrades to WebSearch.
#
# Two assertions, over every src/agents/*.md and src/skills/**/*.md:
#
#   (a) Every agent declaring a non-empty mcpServers entry for a server that
#       IS configured in .mcp.json must grant at least one matching
#       `mcp__<server>__*` tool in its tools: list. Servers NOT configured
#       (stitch, storybook-mcp) are exempt: granting tools for an
#       unconfigured server achieves nothing, and those declarations need a
#       separate configure-or-drop decision.
#
#   (b) Every `mcp__<server>__<tool>` token in agents/skills markdown must
#       name a tool the server actually exposes. Four context7 spellings in
#       this repo's history (resolve, get_library_docs, getLibraryDocs,
#       query_docs) and one memory spelling (add_node) grant NOTHING; they
#       do not exist, and a grant of a nonexistent tool is a silent no-op.
#
# .mcp.json is untracked (runtime file), so the configured-server list and
# the per-server tool rosters are pinned here. Verified against a live
# session's loaded tool list, 2026-08-17. If a server is added to .mcp.json
# or a server's tool surface changes, update the rosters below.
#
# Overridable for differential testing:
#   AGENTS_DIR=<dir> SKILLS_DIR=<dir> bash tests/agents/test-mcp-declared-vs-granted.sh

set -euo pipefail

SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
REPO_ROOT="$(cd "$SCRIPT_DIR/../.." && pwd)"

AGENTS_DIR="${AGENTS_DIR:-$REPO_ROOT/src/agents}"
SKILLS_DIR="${SKILLS_DIR:-$REPO_ROOT/src/skills}"

RED='\033[0;31m'
GREEN='\033[0;32m'
NC='\033[0m'

FAIL=0

# Servers configured in .mcp.json (verified 2026-08-17). stitch and
# storybook-mcp are deliberately absent: not configured.
CONFIGURED_SERVERS="context7 sequential-thinking memory tavily 21st-dev-magic fal hq-knowledge"

# Real tool rosters per server, verified against a live loaded tool list.
# Only servers whose roster we have verified are name-checked in (b).
canonical_tools() {
  case "$1" in
    context7) echo "resolve-library-id query-docs" ;;
    memory)   echo "search_nodes read_graph open_nodes create_entities create_relations add_observations delete_entities delete_observations delete_relations" ;;
    tavily)   echo "tavily_search tavily_extract tavily_crawl tavily_map tavily_research" ;;
    *)        echo "" ;;
  esac
}

# ---------------------------------------------------------------------------
# (a) declared-but-not-granted, per agent
# ---------------------------------------------------------------------------
echo "=== (a) mcpServers declared vs tools granted ==="
for agent_file in "$AGENTS_DIR"/*.md; do
  name="$(basename "$agent_file" .md)"
  case "$name" in README|INDEX|CONTRIBUTING) continue ;; esac

  result="$(node -e '
    const fs = require("fs");
    const content = fs.readFileSync(process.argv[1], "utf8").replace(/\r\n/g, "\n");
    const fmMatch = content.match(/^---\n([\s\S]*?)\n---/);
    if (!fmMatch) process.exit(0);
    const fm = fmMatch[1];

    const singleLine = fm.match(/^mcpServers:\s*\[([^\]]*)\]/m);
    const blockList  = fm.match(/^mcpServers:\s*\n((?:[ \t]*-[ \t]+\S[^\n]*\n?)+)/m);
    let servers = [];
    if (singleLine && singleLine[1].trim()) {
      servers = singleLine[1].split(",").map(s => s.trim()).filter(Boolean);
    } else if (blockList) {
      servers = blockList[1].split("\n").map(l => l.replace(/^[ \t]*-[ \t]+/, "").trim()).filter(Boolean);
    }

    const toolsBlock = fm.match(/^tools:\s*\n((?:[ \t]*(?:-[ \t]+\S[^\n]*|#[^\n]*)\n?)+)/m);
    const tools = toolsBlock
      ? toolsBlock[1].split("\n").map(l => l.replace(/^[ \t]*-[ \t]+/, "").trim()).filter(l => l && !l.startsWith("#"))
      : [];

    for (const srv of servers) {
      const granted = tools.some(t => t.startsWith("mcp__" + srv + "__"));
      process.stdout.write(srv + "|" + (granted ? "GRANTED" : "UNGRANTED") + "\n");
    }
  ' "$agent_file")"

  while IFS='|' read -r srv state; do
    [ -z "$srv" ] && continue
    case " $CONFIGURED_SERVERS " in
      *" $srv "*) : ;;  # configured: check the grant below
      *) continue ;;    # unconfigured: exempt (configure-or-drop is separate)
    esac
    if [ "$state" = "UNGRANTED" ]; then
      echo -e "${RED}FAIL${NC} [$name]: declares mcpServers [$srv] but grants no mcp__${srv}__* tool" >&2
      FAIL=1
    fi
  # pipebuf: bounded-small (at most ~5 "srv|state" lines per agent, far under 512B)
  done <<< "$result"
done

# ---------------------------------------------------------------------------
# (b) every mcp__<server>__<tool> token must name a real tool
# ---------------------------------------------------------------------------
echo "=== (b) tool-name spellings vs real server rosters ==="
for srv in context7 memory tavily; do
  roster="$(canonical_tools "$srv")"

  set +e
  hits="$(grep -rEon "mcp__${srv}__[a-zA-Z_-]+" "$AGENTS_DIR" "$SKILLS_DIR" --include="*.md")"
  rc=$?
  set -e
  if [ "$rc" -gt 1 ]; then
    echo "ERROR: grep failed (rc=$rc) scanning for mcp__${srv}__ tokens" >&2
    exit 1
  fi
  [ "$rc" -eq 1 ] && continue  # no tokens for this server anywhere: nothing to check

  hits_file="$(mktemp)"
  printf '%s\n' "$hits" > "$hits_file"
  while IFS= read -r hit; do
    [ -z "$hit" ] && continue
    file="${hit%%:*}"; rest="${hit#*:}"
    line="${rest%%:*}"; token="${rest#*:}"
    tool="${token#mcp__${srv}__}"
    case " $roster " in
      *" $tool "*) : ;;
      *)
        echo -e "${RED}FAIL${NC} [$file:$line]: $token is not a real $srv tool (real: $roster)" >&2
        FAIL=1
        ;;
    esac
  done < "$hits_file"
  rm -f "$hits_file"
done

if [ "$FAIL" -eq 0 ]; then
  echo -e "${GREEN}PASS${NC}: every declared configured mcpServer is granted, every mcp tool name is real."
  exit 0
else
  echo "FAIL: declared-but-uncallable MCP surface detected (#3461). Fix the issues above." >&2
  exit 1
fi
